import sys,json,hashlib,numpy as np,trimesh
R=Path('/data/recon');color=sys.argv[1];S=R/f'work/clean_models/{color}_cup_fresh';O=R/f'work/{color}_cup';O.mkdir(parents=True,exist_ok=True);proof=json.load(open(S/'SOURCE_PROOF.json'));sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();H=float(proof['height_m']);r0=float(proof['radii_m'][0]);rt=float(proof['radii_m'][-1]);t=.0014;slope=(rt-r0)/H;rf=r0+slope*t;ri=rf-t;rit=rt-t;n=96;theta=np.arange(n)*2*np.pi/n
