def quad(a,b,c,d,label):faces.extend([[a,b,c],[a,c,d]]);labels.extend([label,label])
for k in range(n):
 j=(k+1)%n;quad(k,j,n+j,n+k,'outer_own_fit');quad(n+k,n+j,2*n+j,2*n+k,'outer_own_fit');quad(3*n+k,4*n+k,4*n+j,3*n+j,'inner_wall_prior');quad(2*n+k,2*n+j,4*n+j,4*n+k,'rim_prior');faces.extend([[5*n,j,k],[5*n+1,3*n+k,3*n+j]]);labels.extend(['bottom_prior','interior_floor_prior'])
m=trimesh.Trimesh(V,np.array(faces),process=False);m.fix_normals();assert m.is_volume and m.is_watertight;m.export(O/'mesh.obj');m.export(O/'mesh.ply');pieces=[]
for k in range(n):
 j=(k+1)%n
 for kind,v in [('wall',V[[n+k,n+j,2*n+k,2*n+j,3*n+k,3*n+j,4*n+k,4*n+j]]),('base',V[[5*n,k,j,5*n+1,n+k,n+j]])]:
  p=trimesh.convex.convex_hull(v);assert p.is_volume and p.is_convex;pieces.append((kind,p))
