np.savez_compressed(O/'cavity_preserving_convex.npz',**payload);np.savez_compressed(O/'SURFACE_LABELS.npz',face_kind=np.array(labels),vertices=V,faces=m.faces);source=trimesh.load(S/'mesh_outer_open.ply',process=False);rad=np.linalg.norm(source.vertices[:,:2],axis=1);outer_error=float(np.max(abs(rad-(r0+slope*source.vertices[:,2]))));assert outer_error<1e-7
